function validate([caption]) {
  if (typeof caption !== 'string' || caption.length < 1 || caption.length > 50000) return 'caption needs 1 to 50,000 letters.';
  if (!/^[a-z]+$/.test(caption)) return 'caption uses lowercase English letters only.';
  return null;
}

