function minCostGoodCaption(caption) {
  const n = caption.length;
  if (n < 3) {
    return '';
  }
  const code = Array.from(caption, ch => ch.charCodeAt(0) - 97);
  // dp[i][c]: fewest operations that make caption[i..] good with first letter c.
  const dp = Array.from({ length: n + 1 }, () => new Array(26).fill(Infinity));
  const takeBlock = Array.from({ length: n }, () => new Array(26).fill(false));
  const best = new Array(n + 1).fill(Infinity);
  const bestLetter = new Array(n + 1).fill(0);
  best[n] = 0;

  for (let i = n - 3; i >= 0; i--) {
    for (let c = 0; c < 26; c++) {
      const cost = Math.abs(code[i] - c);
      const extend = cost + dp[i + 1][c];
      const block = cost + Math.abs(code[i + 1] - c) + Math.abs(code[i + 2] - c) + best[i + 3];
      takeBlock[i][c] = block < extend || (block === extend && bestLetter[i + 3] < c);
      dp[i][c] = Math.min(extend, block);
      if (dp[i][c] < best[i]) {
        best[i] = dp[i][c];
        bestLetter[i] = c;
      }
    }
  }

  const result = [];
  let i = 0;
  let letter = bestLetter[0];
  while (i < n) {
    const ch = String.fromCharCode(97 + letter);
    if (takeBlock[i][letter]) {
      result.push(ch, ch, ch);
      i += 3;
      letter = bestLetter[i];
    } else {
      result.push(ch);
      i += 1;
    }
  }
  return result.join('');
}

