function minCostGoodCaption(caption) {
  // best[i] = [cost, text]: the cheapest, then smallest, good rewrite of caption[i..] on its own,
  // trying every first block caption[i..end) and every letter for it.
  const n = caption.length;
  const best = new Array(n + 1).fill(null);
  best[n] = [0, ''];
  for (let i = n - 1; i >= 0; i--) {
    for (let end = i + 3; end <= n; end++) {
      if (!best[end]) continue;
      for (let c = 0; c < 26; c++) {
        let cost = best[end][0];
        for (let k = i; k < end; k++) cost += Math.abs(caption.charCodeAt(k) - 97 - c);
        const text = String.fromCharCode(97 + c).repeat(end - i) + best[end][1];
        if (!best[i] || cost < best[i][0] || (cost === best[i][0] && text < best[i][1])) best[i] = [cost, text];
      }
    }
  }
  return best[0] ? best[0][1] : '';
}

