function generate(rand, size) {
  const n = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 10);
  // Letters come from a random window of the alphabet, in short runs, so ties and near-good strings are common.
  const width = 1 + Math.floor(rand() * (size === 'large' ? 26 : 6));
  const low = Math.floor(rand() * (27 - width));
  let caption = '';
  while (caption.length < n) {
    const letter = String.fromCharCode(97 + low + Math.floor(rand() * width));
    caption += letter.repeat(1 + Math.floor(rand() * 4));
  }
  return [caption.slice(0, n)];
}
